import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"XSS","description":"","frontmatter":{"title":"XSS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/xss.md","filePath":"cs/xss.md","lastUpdated":1789023840000}'),S={name:"cs/xss.md"};function h(_,a,u,E,m,b){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="xss" tabindex="-1">XSS <a class="header-anchor" href="#xss" aria-label="Permalink to &quot;XSS&quot;">​</a></h1><div class="epigraph"><p>脚本与数据若在 HTML/JS 上下文里分不开，攻击者的字符串就会在受害者浏览器里以该源的身份执行。这是注入课在 Web 上的实例：完整中介失败在页面拼接。</p><footer>—— 据 OWASP XSS；CWE-79；对照[同源与 CSRF](/cs/same-origin-csrf)、[注入](/cs/injection-boundary)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/binary-hardening-obfuscation">二进制加固</a>结束软件安全。Web 单元从浏览器开始。主干同源课管 Cookie；缺口是<strong>脚本注入</strong>：反射、存储、DOM。不给可复制的恶意脚本。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>模板把用户输入写进 HTML。若未按上下文编码，输入可变成标签或事件处理器。存储型让每位访客执行。缺口是上下文编码与可信类型，不是过滤尖括号清单。</p><h3 id="不是只防-script-标签" tabindex="-1">不是只防 script 标签 <a class="header-anchor" href="#不是只防-script-标签" aria-label="Permalink to &quot;不是只防 script 标签&quot;">​</a></h3><p>事件属性、CSS、URL 方案都是上下文。编码函数必须匹配上下文。</p><p><span class="marginnote">OWASP。本课禁止 XSS payload 教程。CSP 下一课是纵深，不是根治。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分三种 XSS。防御：模板自动转义、Trusted Types、HttpOnly 不阻止 XSS 操 DOM。下一课 CSP 限制脚本源。</p>',12)),(e(),n(c,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E4%B8%8D%E5%8F%AF%E4%BF%A1%E4%B8%B2%22%5D%20--%3E%20CTX%5B%22HTML%2FJS%2FURL%20%E4%B8%8A%E4%B8%8B%E6%96%87%22%5D%0A%20%20CTX%20--%3E%20EXEC%5B%22%E4%BB%A5%E8%AF%A5%E6%BA%90%E6%89%A7%E8%A1%8C%22%5D%0A%20%20IN%20--%3E%20ESC%5B%22%E6%8C%89%E4%B8%8A%E4%B8%8B%E6%96%87%E7%BC%96%E7%A0%81%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>SOP 把脚本权限给源。XSS 等于把权限借给输入。会话 Cookie 可被同源于脚本读（除非 HttpOnly，但仍可发请求）。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零 payload。CSP 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>内存利用之后，Web 的经典注入是 XSS。</li><li>按上下文编码；过滤清单不够。</li><li>XSS 借用源的权限。</li><li>下一课 CSP。</li><li>出处：OWASP XSS；CWE-79；<a href="/cs/injection-boundary">injection-boundary</a>。</li></ul>',8))])}const C=o(S,[["render",h]]);export{A as __pageData,C as default};
